//! Bounded proof that an interrupted atlas output was generated by this project.
use serde::{Deserialize, Serialize};
use std::{
    fs,
    io::{Read, Write},
    path::{Path, PathBuf},
};

pub(crate) const FILE: &str = ".kiln-atlas-generations.json";
pub(crate) const LOCK: &str = ".kiln-atlas.lock";
const LIMIT: usize = 512 * 1024;

#[derive(Clone, Serialize, Deserialize)]
pub(crate) struct Generation {
    pub project: String,
    pub atlas: String,
    pub output: String,
    pub hash: String,
}
#[derive(Serialize, Deserialize)]
struct Ledger {
    version: u32,
    generations: Vec<Generation>,
}

fn private_path(root: &Path, name: &str) -> Result<PathBuf, String> {
    let path = root.join(name);
    if let Ok(metadata) = fs::symlink_metadata(&path) {
        if !metadata.is_file() || metadata.file_type().is_symlink() {
            return Err("Atlas transaction metadata must be an ordinary file".into());
        }
    }
    Ok(path)
}

pub(crate) fn lock(root: &Path) -> Result<fs::File, String> {
    let file = fs::OpenOptions::new()
        .read(true)
        .write(true)
        .create(true)
        .truncate(false)
        .open(private_path(root, LOCK)?)
        .map_err(|e| e.to_string())?;
    file.try_lock()
        .map_err(|e| format!("Atlas publication lock unavailable: {e}"))?;
    Ok(file)
}

pub(crate) fn read(root: &Path) -> Result<Vec<Generation>, String> {
    let path = private_path(root, FILE)?;
    let file = match fs::File::open(path) {
        Ok(file) => file,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(Vec::new()),
        Err(error) => return Err(error.to_string()),
    };
    let mut bytes = Vec::new();
    file.take(LIMIT as u64 + 1)
        .read_to_end(&mut bytes)
        .map_err(|e| e.to_string())?;
    if bytes.len() > LIMIT {
        return Err("Atlas provenance exceeds 512 KiB; retain it for recovery".into());
    }
    let ledger: Ledger =
        serde_json::from_slice(&bytes).map_err(|e| format!("Invalid atlas provenance: {e}"))?;
    if ledger.version != 1 || ledger.generations.len() > 4096 {
        return Err("Unsupported or oversized atlas provenance; retain it for recovery".into());
    }
    Ok(ledger.generations)
}

struct Temporary(PathBuf);
impl Drop for Temporary {
    fn drop(&mut self) {
        let _ = fs::remove_file(&self.0);
    }
}

/// A create-new temporary name must survive process-counter reuse after crashes.
pub(crate) fn replace(path: &Path, bytes: &[u8]) -> Result<(), String> {
    replace_with(path, bytes, kiln_core::next_id)
}

fn replace_with(path: &Path, bytes: &[u8], mut next: impl FnMut() -> u64) -> Result<(), String> {
    let parent = path.parent().ok_or("Missing atlas directory")?;
    for _ in 0..4096 {
        let candidate = parent.join(format!(".kiln-atlas-{}.tmp", next()));
        let file = fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&candidate);
        let mut file = match file {
            Ok(file) => file,
            Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => {
                continue;
            }
            Err(error) => return Err(error.to_string()),
        };
        let temporary = Temporary(candidate);
        file.write_all(bytes).map_err(|e| e.to_string())?;
        file.sync_all().map_err(|e| e.to_string())?;
        drop(file);
        fs::rename(&temporary.0, path).map_err(|e| e.to_string())?;
        return Ok(());
    }
    Err("Too many interrupted atlas temporary files; preserve them before cleanup".into())
}

pub(crate) fn write(root: &Path, generations: Vec<Generation>) -> Result<(), String> {
    if generations.len() > 4096 {
        return Err("Save Project before building more atlas generations".into());
    }
    let bytes = serde_json::to_vec(&Ledger {
        version: 1,
        generations,
    })
    .map_err(|e| e.to_string())?;
    if bytes.len() > LIMIT {
        return Err("Save Project before building more atlas generations".into());
    }
    replace(&private_path(root, FILE)?, &bytes)
}

pub(crate) fn owns(
    root: &Path,
    project: &str,
    atlas: &str,
    output: &str,
    hash: &str,
) -> Result<bool, String> {
    Ok(read(root)?
        .iter()
        .any(|g| g.project == project && g.atlas == atlas && g.output == output && g.hash == hash))
}

pub(crate) fn record(
    root: &Path,
    project: &str,
    atlas: &str,
    output: &str,
    hash: &str,
) -> Result<(), String> {
    let mut generations = read(root)?;
    if generations
        .iter()
        .any(|g| g.project == project && g.atlas == atlas && g.output == output && g.hash == hash)
    {
        return Ok(());
    }
    generations.push(Generation {
        project: project.into(),
        atlas: atlas.into(),
        output: output.into(),
        hash: hash.into(),
    });
    write(root, generations)
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn existing_interrupted_temporary_files_are_preserved_and_skipped() {
        let root = tempfile::tempdir().unwrap();
        let orphan = root.path().join(".kiln-atlas-1.tmp");
        fs::write(&orphan, b"retained earlier generation").unwrap();
        let mut ids = [1, 2].into_iter();
        replace_with(&root.path().join("output.png"), b"new output", || {
            ids.next().unwrap()
        })
        .unwrap();
        assert_eq!(fs::read(&orphan).unwrap(), b"retained earlier generation");
        assert_eq!(
            fs::read(root.path().join("output.png")).unwrap(),
            b"new output"
        );
        assert!(!root.path().join(".kiln-atlas-2.tmp").exists());
    }
}
